// Build the AI prompt with structured email schema
// Each segment gets a tailored prompt that produces structured pieces,
// which a downstream step assembles into a clean HTML template.

const segmentName = $('Config').item.json.segment_name;

const brandContext = `
You write lifecycle, segmented campaign, and customer activation emails for {{COMPANY_NAME}}.

{{COMPANY_NAME}} is a China-to-Africa shipping, freight coordination, export preparation, and delivery visibility platform.

REAL CAPABILITIES:
Use only the capabilities listed here. Never invent additional services.

Core capabilities:
- China warehouses in Guangzhou where customers can send goods from Chinese e-commerce platforms, direct suppliers, and factories
- Support for shipping goods from China into African markets
- Air freight options, often 7-14 days depending on route and operating conditions
- Sea freight options, often 40-60 days depending on route and operating conditions
- Export preparation and freight coordination from China
- Customs clearance support or handling where applicable
- Tracking dashboard with shipment milestones
- Shipping dispatches usually happen 1-2 times per week
- Countries served: Ghana, Kenya, South Africa, Nigeria, Zimbabwe, Zambia

Country-specific capabilities:
- Ghana: Accra warehouse, COD in GHS, self-operated last-mile delivery in Accra
- Kenya: Nairobi warehouse, COD in KES, self-operated last-mile delivery in Nairobi
- South Africa: Johannesburg warehouse, China-to-South Africa shipping support, freight planning, tracking visibility
- Nigeria: China-to-Nigeria shipping support, customs handling, air or sea options, tracking visibility
- Zambia: China-to-Zambia shipping support, customs handling, air or sea options, tracking visibility
- Zimbabwe: China-to-Zimbabwe shipping support, customs handling, air or sea options, tracking visibility

DO NOT CLAIM:
- Do not mention package consolidation
- Do not mention cargo consolidation
- Do not say {{COMPANY_NAME}} combines packages from multiple suppliers
- Do not say {{COMPANY_NAME}} groups several orders into one shipment
- Do not say {{COMPANY_NAME}} merges shipments
- Do not promise fixed delivery dates
- Do not promise guaranteed transit times
- Do not mention discounts, promo codes, loyalty programs, free shipping, or unrealistic savings
- Do not claim COD outside Ghana or Kenya unless explicitly instructed
- Do not claim self-operated last-mile delivery outside Accra or Nairobi unless explicitly instructed
- Do not invent warehouse locations, prices, dates, routes, discounts, or service guarantees

VOICE:
Confident, warm, direct, and operational.
Treat the reader as a business person.
Use plain English.
Use short sentences.
Sound like a logistics partner, not a promo brand.
Focus on planning, route choice, export preparation, tracking visibility, customs handling, and shipment workflow.
Avoid hype and exaggerated promises.

EMAIL STRUCTURE:
You must produce the following fields:
- subject: under 50 characters, action-oriented, no clickbait
- headline_kicker: short tagline above the headline
- headline: H1-style title, under 60 characters
- intro_paragraph: 2-3 sentences setting up the email's value
- callout_title: short title for an optional bullet section. Use "" if no bullets are needed.
- callout_bullets: 0-3 short bullets. Each bullet must be under 18 words.
- closing_paragraph: 1-2 sentences leading into the CTA
- cta_label: 2-4 words on the button
- cta_url_token: exactly one of: plan-shipment, get-quote, view-tracking, view-dashboard

CTA TOKEN RULES:
- plan-shipment: use when asking the user to prepare, start, or plan a shipment
- get-quote: use when the email focuses on pricing, freight estimate, or route cost
- view-tracking: use when the email focuses on shipment progress
- view-dashboard: use when the email asks the user to check their account, shipment history, or dashboard

WRITING RULES:
- Mention only capabilities listed above
- Keep the email practical and specific
- Do not use "no pressure", "not a sales pitch", "we miss you", "just checking in", or "last chance"
- Do not use hype, fake urgency, or exaggerated claims
- Do not use "reply to this email" as a CTA because the sending address may be noreply
- Do not include HTML in any field
- Do not include meta-commentary about the email
- Do not start every email with "We help"
- Avoid repeating the same capability in the intro, bullets, and closing
- When mentioning Chinese e-commerce platforms, mention them together as Taobao, Pinduoduo, and 1688, and also mention direct suppliers or factories
`;

const prompts = {
  delivered_orders: {
    systemPrompt: brandContext,
    prompt: `Email to a customer whose shipment has just arrived in Africa from China. Acknowledge the shipment arrival in the intro, then give them one concrete next step, such as checking their dashboard or planning their next shipment. Skip the callout box unless you have 2-3 genuinely useful parallel points. Do not mention package consolidation. CTA: plan-shipment.`
  },

  inactive_users: {
    systemPrompt: brandContext,
    prompt: `Email to a customer who has not shipped in 30+ days. Lead with one practical reason to prepare their next China shipment early, such as choosing the right freight mode, preparing goods before dispatch, or checking shipment timing. The callout box can list 2-3 concrete actions they can take. Do not mention package consolidation. CTA: plan-shipment.`
  },

  repeat_customers: {
    systemPrompt: brandContext,
    prompt: `Email to a customer who has shipped multiple times. Treat them as experienced. Give one operationally useful suggestion, such as reviewing shipment milestones, choosing air for urgent stock, or planning sea freight earlier for larger cargo. Do not mention package consolidation. CTA: view-dashboard.`
  },

  agents: {
    systemPrompt: brandContext + `\n\nAUDIENCE NOTE: This is a shipping AGENT or partner who refers customers, not an end customer.`,
    prompt: `Brief partner update for a {{COMPANY_NAME}} shipping agent. Acknowledge the partnership in one sentence in the intro. The callout box may list things they can show clients, such as dashboard tracking, customs handling where applicable, air or sea options, and local payment options where available. Do not mention package consolidation. CTA: view-dashboard.`
  },

  country_gh: {
    systemPrompt: brandContext,
    prompt: `Email to customers in Ghana. Lead with Ghana-relevant support: the Accra warehouse, COD in GHS, self-operated last-mile delivery in Accra, customs handling where applicable, and shipment milestone visibility. Do not mention package consolidation. CTA: plan-shipment.`
  },

  country_ke: {
    systemPrompt: brandContext,
    prompt: `Email to customers in Kenya. Lead with Kenya-relevant support: the Nairobi warehouse, COD in KES, self-operated last-mile delivery in Nairobi, customs handling where applicable, and shipment milestone visibility. Do not mention package consolidation. CTA: plan-shipment.`
  },

  country_za: {
    systemPrompt: brandContext,
    prompt: `Email to customers in South Africa. Focus on China-to-South Africa shipping support, the Johannesburg warehouse where relevant, freight planning, tracking visibility, and choosing air or sea based on urgency. Do not mention COD, self-operated last-mile delivery, or package consolidation. CTA: plan-shipment.`
  },

  country_ng: {
    systemPrompt: brandContext,
    prompt: `Email to customers in Nigeria. Focus on China-to-Nigeria shipping support, customs handling where applicable, tracking visibility, and air or sea freight options. Do not mention COD, self-operated last-mile delivery, or package consolidation. CTA: plan-shipment.`
  },

  country_zm: {
    systemPrompt: brandContext,
    prompt: `Email to customers in Zambia. Focus on China-to-Zambia shipping support, customs handling where applicable, air or sea freight options, and shipment tracking visibility. Do not mention COD, self-operated last-mile delivery, or package consolidation. CTA: plan-shipment.`
  },

  country_zw: {
    systemPrompt: brandContext,
    prompt: `Email to customers in Zimbabwe. Focus on China-to-Zimbabwe shipping support, customs handling where applicable, air or sea freight options, and shipment tracking visibility. Do not mention COD, self-operated last-mile delivery, or package consolidation. CTA: plan-shipment.`
  },

  country_cn: {
    systemPrompt: brandContext + `\n\nAUDIENCE NOTE: These users are registered with a China-based account. They are likely suppliers, warehouse-side users, or business partners on the China side.`,
    prompt: `Brief professional note for a partner on the China side. Acknowledge the working relationship. Reference shipment processing, export preparation, or dashboard visibility. Do not mention package consolidation. CTA: view-dashboard.`
  },

  individual_users: {
    systemPrompt: brandContext,
    prompt: `Email to individual personal-use customers. Focus on one simple capability that helps personal shoppers, such as sending goods to the Guangzhou warehouse from Taobao, Pinduoduo, 1688, direct suppliers, or factories, plus checking shipment milestones. Do not mention package consolidation. CTA: view-dashboard.`
  },

  company_users: {
    systemPrompt: brandContext,
    prompt: `Email to business customers shipping commercial goods from China. Focus on freight planning, weekly dispatch rhythm, customs handling where applicable, tracking visibility, and choosing the right shipping mode. Do not mention package consolidation. CTA: plan-shipment.`
  },

  price_sensitive_users: {
    systemPrompt: brandContext,
    prompt: `Email to customers likely to care about shipment cost planning. Focus on choosing the right route, comparing air and sea options, and preparing cargo details before requesting a quote. Do not mention discounts, unrealistic savings, or package consolidation. CTA: get-quote.`
  },

  tracking_engaged_users: {
    systemPrompt: brandContext,
    prompt: `Email to customers who frequently check shipment progress. Focus on shipment milestones, dashboard visibility, and using tracking information to plan receiving or delivery. Do not mention real-time guarantees or package consolidation. CTA: view-tracking.`
  },

  _default: {
    systemPrompt: brandContext,
    prompt: `Brief check-in to a {{COMPANY_NAME}} customer. Reference one concrete {{COMPANY_NAME}} capability, such as freight planning, export preparation, customs handling where applicable, or shipment milestone visibility. Do not mention package consolidation. CTA: plan-shipment.`
  }
};

const config = prompts[segmentName] || prompts._default;

return [
  {
    json: {
      prompt: config.prompt,
      systemPrompt: config.systemPrompt,
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          subject: {
            type: 'string',
            maxLength: 50
          },
          headline_kicker: {
            type: 'string',
            maxLength: 50
          },
          headline: {
            type: 'string',
            maxLength: 60
          },
          intro_paragraph: {
            type: 'string'
          },
          callout_title: {
            type: 'string',
            maxLength: 50
          },
          callout_bullets: {
            type: 'array',
            items: {
              type: 'string',
              maxLength: 90
            },
            maxItems: 3
          },
          closing_paragraph: {
            type: 'string'
          },
          cta_label: {
            type: 'string',
            maxLength: 30
          },
          cta_url_token: {
            type: 'string',
            enum: [
              'plan-shipment',
              'get-quote',
              'view-tracking',
              'view-dashboard'
            ]
          }
        },
        required: [
          'subject',
          'headline_kicker',
          'headline',
          'intro_paragraph',
          'callout_title',
          'callout_bullets',
          'closing_paragraph',
          'cta_label',
          'cta_url_token'
        ]
      },
      maxTokens: 900,
      temperature: 0.45
    }
  }
];

// Build per-recipient items: combines recipients with the AI service's structured content
// Wraps the structured pieces in an HTML template before sending
// Personalizes [First Name] / {{first_name}} placeholders with each recipient's actual name

const recipients = $('Fetch eligible recipients').all();
const aiResponse = $('Call AI service').first().json;
const config = $('Config').first().json;

const content = aiResponse.data || aiResponse;

// CTA URL token → real URL
const CTA_URLS = {
  'plan-shipment': 'https://app.example.com/auth/login',
  'get-quote': 'https://app.example.com/estimates',
  'view-tracking': 'https://app.example.com/tracker',
  'view-dashboard': 'https://app.example.com/'
};

// Dedupe by email
const seen = new Set();
const uniqueRecipients = recipients.filter(item => {
  const email = item.json.email;
  if (!email || seen.has(email)) return false;
  seen.add(email);
  return true;
});

// Personalization helper — replace any common placeholder variant
const personalize = (text, firstName) => {
  if (!text) return '';
  return text
    .replace(/\[First Name\]/gi, firstName)
    .replace(/\{\{first_name\}\}/gi, firstName)
    .replace(/\{\{firstName\}\}/gi, firstName)
    .replace(/\{first_name\}/gi, firstName)
    .replace(/\{FirstName\}/gi, firstName);
};

// Escape HTML to prevent injection from any field
const escapeHtml = (str) => {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
};

// Build the HTML email template
const buildHtml = (c, firstName, ctaUrl) => {
  const headline = escapeHtml(personalize(c.headline, firstName));
  const kicker = escapeHtml(personalize(c.headline_kicker || '', firstName));
  const intro = escapeHtml(personalize(c.intro_paragraph, firstName));
  const closing = escapeHtml(personalize(c.closing_paragraph, firstName));
  const ctaLabel = escapeHtml(c.cta_label);

  // Callout block — only render if there are bullets
  const bullets = (c.callout_bullets || []).filter(b => b && b.trim());
  let calloutBlock = '';
  if (bullets.length > 0) {
    const calloutTitle = escapeHtml(personalize(c.callout_title || '', firstName));
    const bulletList = bullets
      .map(b => `<li style="margin: 0 0 8px 0; color: #333; line-height: 1.5;">${escapeHtml(personalize(b, firstName))}</li>`)
      .join('');
    calloutBlock = `
      <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin: 24px 0;">
        <tr>
          <td style="background: #FFF4E6; border-left: 4px solid #FF6B1A; padding: 20px 24px; border-radius: 4px;">
            ${calloutTitle ? `<div style="color: #FF6B1A; font-weight: 600; font-size: 14px; margin-bottom: 12px; text-transform: uppercase; letter-spacing: 0.5px;">${calloutTitle}</div>` : ''}
            <ul style="margin: 0; padding-left: 20px;">${bulletList}</ul>
          </td>
        </tr>
      </table>`;
  }

  return `
<table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="background: #f5f5f5; padding: 24px 0;">
  <tr>
    <td align="center">
      <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="600" style="max-width: 600px; background: #ffffff; border-radius: 8px; overflow: hidden; font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;">

        <!-- Orange header band -->
        <tr>
          <td style="background: #FF6B1A; padding: 28px 32px; text-align: center;">
            <div style="color: #ffffff; font-size: 18px; font-weight: 700; letter-spacing: 1px;">{{COMPANY_NAME}}</div>
            ${kicker ? `<div style="color: #ffffff; opacity: 0.9; font-size: 14px; margin-top: 6px;">${kicker}</div>` : ''}
          </td>
        </tr>

        <!-- Body -->
        <tr>
          <td style="padding: 32px;">
            <h1 style="color: #1a1a1a; font-size: 22px; font-weight: 600; margin: 0 0 16px 0; line-height: 1.3;">${headline}</h1>

            <p style="color: #444; font-size: 15px; line-height: 1.6; margin: 0 0 16px 0;">Hi ${escapeHtml(firstName)},</p>

            <p style="color: #444; font-size: 15px; line-height: 1.6; margin: 0;">${intro}</p>

            ${calloutBlock}

            <p style="color: #444; font-size: 15px; line-height: 1.6; margin: 16px 0 24px 0;">${closing}</p>

            <!-- CTA button -->
            <table role="presentation" cellpadding="0" cellspacing="0" border="0" style="margin: 8px 0;">
              <tr>
                <td style="background: #FF6B1A; border-radius: 4px;">
                  <a href="${ctaUrl}" style="display: inline-block; padding: 14px 32px; color: #ffffff; text-decoration: none; font-weight: 600; font-size: 15px;">${ctaLabel}</a>
                </td>
              </tr>
            </table>
          </td>
        </tr>

        <!-- Footer -->
        <tr>
          <td style="padding: 20px 32px; background: #fafafa; border-top: 1px solid #eee; text-align: center;">
            <div style="color: #888; font-size: 13px; line-height: 1.5;">Serving Ghana, Kenya, South Africa, Nigeria, Zimbabwe, Zambia.</div>
          </td>
        </tr>

      </table>
    </td>
  </tr>
</table>`;
};

// Build send items
const items = uniqueRecipients.map(item => {
  const recipient = item.json;
  const targetEmail = config.test_mode ? config.test_recipient_email : recipient.email;
  const firstName = (recipient.user_name || '').trim().split(' ')[0] || 'there';
  const ctaUrl = CTA_URLS[content.cta_url_token] || CTA_URLS['view-dashboard'];

  const finalHtml = buildHtml(content, firstName, ctaUrl);

  // Plain-text fallback for clients that prefer it
  const bullets = (content.callout_bullets || [])
    .filter(b => b && b.trim())
    .map(b => `• ${personalize(b, firstName)}`)
    .join('\n');

  const plainText = `Hi ${firstName},

${personalize(content.intro_paragraph, firstName)}

${content.callout_title && bullets ? content.callout_title.toUpperCase() + '\n' + bullets + '\n' : ''}
${personalize(content.closing_paragraph, firstName)}

${content.cta_label}: ${ctaUrl}

— {{COMPANY_NAME}}
Serving Ghana, Kenya, South Africa, Nigeria, Zimbabwe, Zambia.`;

  return {
    json: {
      user_id: recipient.user_id,
      original_email: recipient.email,
      target_email: targetEmail,
      user_name: recipient.user_name,
      first_name: firstName,
      segment_name: recipient.segment_name,
      subject: personalize(content.subject, firstName),
      body_html: finalHtml,
      body_text: plainText,
      cta_label: content.cta_label,
      cta_url: ctaUrl,
      shadow_mode: config.shadow_mode
    }
  };
});

return items;

parameters.query:
UPDATE user_segments
SET campaign_last_sent_at = NOW()
WHERE user_id = {{ $('Loop one at a time').item.json.user_id }}
  AND segment_name = '{{ $('Loop one at a time').item.json.segment_name }}';
